"""Generated bytes on one fixed inactive native peer; no protected resources."""
from contextlib import contextmanager
from dataclasses import FrozenInstanceError, asdict
import copy
import hashlib
import inspect
import math
import os
from pathlib import Path
import tempfile
import threading
import time
import unittest
from unittest.mock import patch

from core import broker_synthetic_payload_transport as native
from core import broker_synthetic_payload_peer as process
from core.broker_process import BrokerProcessError
from core.broker_synthetic_payload_protocol import SyntheticPayloadExchange


class SyntheticPayloadTransportTests(unittest.TestCase):
    DATA = b'SecurityBrightness generated transport test\x00\xff\n'

    def setUp(self):
        self.gate = None

    def new(self, payload=None, **options):
        if payload is None: payload = self.DATA
        self.gate = native.SyntheticPayloadTransport(payload, **options)
        return self.gate

    def diagnostic(self):
        value = self.gate.inspect()
        self.assertEqual(set(value), {'state', 'payload_may_have_been_visible',
            'payload_frame_bytes_written', 'cleanup_confirmed'})
        self.assertIs(type(value['state']), str)
        for name in ('payload_may_have_been_visible', 'cleanup_confirmed'):
            self.assertIs(type(value[name]), bool)
        self.assertIs(type(value['payload_frame_bytes_written']), int)
        self.assertGreaterEqual(value['payload_frame_bytes_written'], 0)
        self.assertLessEqual(value['payload_frame_bytes_written'], 8192 + 36)
        self.assertNotIn('data', value)
        self.assertNotIn('payload', value)
        self.assertNotIn('released_bytes', value)
        return value

    def rejected(self, operation=None, *, visible=None, cleanup=True):
        with self.assertRaises(native.SyntheticPayloadTransportError) as error:
            (operation or self.gate.run)()
        self.assertNotIn(repr(self.DATA), str(error.exception))
        value = self.diagnostic()
        self.assertNotEqual(value['state'], 'peer_discarded')
        if visible is not None:
            self.assertIs(value['payload_may_have_been_visible'], visible)
            self.assertEqual(value['state'], 'outcome_unknown' if visible else value['state'])
        self.assertIs(value['cleanup_confirmed'], cleanup)
        return value

    def helper(self, *, prefix='', ending=''):
        directory = tempfile.TemporaryDirectory(); self.addCleanup(directory.cleanup)
        path = Path(directory.name) / 'generated-payload-fault.py'
        root = str(Path(__file__).resolve().parent.parent)
        path.write_text('import sys,os,time\nsys.path.insert(0,' + repr(root) + ')\n'
            'from core import broker_synthetic_payload_entry as entry\n' + prefix +
            '\nentry.run()\n' + ending, encoding='utf-8')
        return patch.object(process._SyntheticPayloadPeer, '_entry_path', return_value=path)

    @contextmanager
    def payload_write(self, operation):
        """Fault only the actual payload frame, after genuine native readiness."""
        original_payload, original_write = SyntheticPayloadExchange.payload, os.write
        active, reached = [False], []
        def payload(codec, data):
            value = original_payload(codec, data)
            active[0] = True
            return value
        def write(fd, data):
            if active[0]:
                reached.append(len(data))
                return operation(original_write, fd, data)
            return original_write(fd, data)
        with patch.object(SyntheticPayloadExchange, 'payload', payload), patch.object(native.os, 'write', write):
            yield reached

    def ready_fault(self, operation):
        original, reached = SyntheticPayloadExchange.accept_ready, []
        def ready(codec, frame):
            value = original(codec, frame)
            self.assertIsNone(self.gate._issued_child.poll())
            reached.append(True)
            operation()
            return value
        with patch.object(SyntheticPayloadExchange, 'accept_ready', ready):
            value = self.rejected(visible=False)
        self.assertEqual(reached, [True], 'fault follows authenticated original native readiness')
        return value

    def receipt_fault(self, operation, *, cleanup=True):
        original, reached = SyntheticPayloadExchange.accept_receipt, []
        def receipt(codec, frame):
            child = self.gate._issued_child
            self.assertEqual(child.poll(), 0)
            value = original(codec, frame)
            reached.append(True)
            operation(value)
            return value
        with patch.object(SyntheticPayloadExchange, 'accept_receipt', receipt):
            value = self.rejected(visible=True, cleanup=cleanup)
        self.assertEqual(reached, [True], 'fault follows exact receipt and original zero process exit')
        return value

    def success(self, payload=None, **options):
        gate = self.new(payload, **options)
        data = self.DATA if payload is None else payload
        value = gate.run()
        self.assertEqual((value.outcome, value.byte_count, value.digest),
            ('peer_discarded', len(data), hashlib.sha256(data).hexdigest()))
        self.assertIs(type(value.canonical_binding), bytes)
        self.assertLessEqual(len(value.canonical_binding), 8192)
        self.assertEqual(value.binding_digest, hashlib.sha256(value.canonical_binding).hexdigest())
        self.assertNotIn('data', asdict(value)); self.assertNotIn('released_bytes', asdict(value))
        with self.assertRaises(TypeError): bool(value)
        with self.assertRaises(FrozenInstanceError): value.outcome = 'allow'
        current = self.diagnostic()
        self.assertEqual(current['state'], 'peer_discarded')
        self.assertIs(current['payload_may_have_been_visible'], True)
        self.assertIs(current['cleanup_confirmed'], True)
        self.assertGreater(current['payload_frame_bytes_written'], len(data))
        gate._issued_child._retired()
        self.assertEqual(gate._issued_child._exit, 0)
        return value

    def test_real_fixed_peer_discards_binary_generated_bytes_and_joins(self):
        self.success()

    def test_real_empty_payload_still_crosses_one_use_frame_boundary(self):
        self.success(b'')

    def test_real_one_byte_payload(self):
        self.success(b'\x00')

    def test_real_maximum_payload_remains_bounded(self):
        self.success(bytes(range(256)) * 16)

    def test_constructor_accepts_no_endpoint_file_handle_app_authority_or_executor(self):
        signature = inspect.signature(native.SyntheticPayloadTransport)
        self.assertEqual(list(signature.parameters), ['payload', 'timeout'])
        for field in ('path', 'endpoint', 'handle', 'application', 'credential', 'approval', 'executor'):
            with self.subTest(field=field), self.assertRaises(TypeError):
                native.SyntheticPayloadTransport(self.DATA, **{field: 'caller'})
        self.assertEqual(list(inspect.signature(process._SyntheticPayloadPeer).parameters), [])
        gate = self.new()
        for field in ('authorize', 'publish', 'read_file', 'execute', 'release', 'acquire'):
            self.assertFalse(hasattr(gate, field))
        self.assertEqual(process._SyntheticPayloadPeer._entry_path(None).name,
            'broker_synthetic_payload_entry.py')

    def test_constructor_rejects_mutable_text_foreign_types_and_bytes_subclasses(self):
        class ForeignBytes(bytes): pass
        for value in (None, True, 1, '', self.DATA.decode('latin1'), bytearray(self.DATA),
                      memoryview(self.DATA), ForeignBytes(self.DATA), {'data': self.DATA}):
            with self.subTest(type=type(value)), self.assertRaises((TypeError, ValueError, native.SyntheticPayloadTransportError)):
                native.SyntheticPayloadTransport(value)

    def test_constructor_rejects_oversized_payload_before_native_launch(self):
        with patch.object(native, '_SyntheticPayloadPeer') as launch:
            with self.assertRaises((TypeError, ValueError, native.SyntheticPayloadTransportError)):
                native.SyntheticPayloadTransport(b'x' * 4097)
            launch.assert_not_called()

    def test_constructor_rejects_malformed_or_unbounded_deadlines(self):
        for value in (None, True, False, 0, -1, 5.0001, math.inf, -math.inf, math.nan, '1'):
            with self.subTest(value=value), self.assertRaises((TypeError, ValueError, native.SyntheticPayloadTransportError)):
                native.SyntheticPayloadTransport(self.DATA, timeout=value)

    def test_inspect_is_detached_and_cannot_manufacture_state_or_visibility(self):
        self.new(); first = self.diagnostic()
        self.assertEqual(first, dict(state='not_started', payload_may_have_been_visible=False,
            payload_frame_bytes_written=0, cleanup_confirmed=False))
        first.update(state='peer_discarded', payload_may_have_been_visible=True, cleanup_confirmed=True)
        self.assertEqual(self.diagnostic()['state'], 'not_started')

