    def test_multiple_native_partial_writes_complete_exact_bounded_frame(self):
        self.new()
        def short(original, fd, data): return original(fd, data[:7])
        with self.payload_write(short) as reached:
            result = self.gate.run()
        self.assertGreater(len(reached), 2)
        self.assertEqual(result.digest, hashlib.sha256(self.DATA).hexdigest())
        self.assertEqual(self.diagnostic()['state'], 'peer_discarded')

    def test_partial_payload_write_then_cancel_is_unknown_and_spent(self):
        self.new()
        def short(original, fd, data):
            count = original(fd, data[:7]); self.gate.cancel(); return count
        with self.payload_write(short) as reached:
            value = self.rejected(visible=True)
        self.assertEqual(len(reached), 1)
        self.assertEqual(value['payload_frame_bytes_written'], 7)
        self.assertEqual(self.gate._origin.buffer, bytearray())
        self.rejected(visible=True)

