    def test_single_original_owner_alias_mutation_rejects_and_wipes_original_only(self):
        for name in ('_origin', '_issued_origin', '_recovery_origin'):
            with self.subTest(name=name):
                self.new(); original = self.gate._origin; foreign = bytearray(b'foreign')
                codec_ready = SyntheticPayloadExchange.accept_ready; reached = []
                def ready(codec, frame):
                    result = codec_ready(codec, frame); reached.append(True)
                    setattr(self.gate, name, foreign); return result
                try:
                    with patch.object(SyntheticPayloadExchange, 'accept_ready', ready), \
                            self.assertRaises(native.SyntheticPayloadTransportError):
                        self.gate.run()
                finally:
                    setattr(self.gate, name, original)
                self.assertEqual(reached, [True])
                self.assertEqual(original.buffer, bytearray())
                self.assertEqual(foreign, bytearray(b'foreign'))
                self.assertEqual(self.diagnostic()['state'], 'failed_before_payload')

