    def test_foreign_child_field_never_selects_a_foreign_cleanup_target(self):
        class Foreign:
            def close(self): raise AssertionError('foreign cleanup invoked')
            def _retired(self): raise AssertionError('foreign retirement invoked')
        for name in ('_child', '_issued_child'):
            with self.subTest(name=name):
                self.new(); original_ready = SyntheticPayloadExchange.accept_ready
                original_child = []
                def ready(codec, frame):
                    value = original_ready(codec, frame)
                    original_child.append(self.gate._issued_child)
                    setattr(self.gate, name, Foreign()); return value
                with patch.object(SyntheticPayloadExchange, 'accept_ready', ready):
                    self.rejected(visible=False)
                self.assertEqual(len(original_child), 1)
                original_child[0]._retired()

