    def test_prestart_cancel_noop_wipe_is_spent_and_cleanup_unconfirmed_without_launch(self):
        self.new()
        with patch.object(native.SyntheticPayloadTransport, '_wipe', return_value=None):
            self.rejected(self.gate.cancel, visible=False, cleanup=False)
        self.assertEqual(self.diagnostic()['state'], 'cancelled_before_payload')
        with patch.object(native, '_SyntheticPayloadPeer') as launch:
            self.rejected(visible=False, cleanup=False); launch.assert_not_called()
        native.SyntheticPayloadTransport._wipe(self.gate._origin)

    def test_prestart_owner_alias_damage_and_noop_wipe_cannot_reopen_attempt(self):
        self.new(); original = self.gate._origin; self.gate._origin = None
        try:
            with patch.object(native.SyntheticPayloadTransport, '_wipe', return_value=None), \
                    patch.object(native, '_SyntheticPayloadPeer') as launch:
                with self.assertRaises(native.SyntheticPayloadTransportError): self.gate.run()
                launch.assert_not_called()
        finally: self.gate._origin = original
        value = self.diagnostic()
        self.assertEqual(value['state'], 'failed_before_payload')
        self.assertIs(value['cleanup_confirmed'], False)
        with patch.object(native, '_SyntheticPayloadPeer') as launch:
            self.rejected(visible=False, cleanup=False); launch.assert_not_called()
        native.SyntheticPayloadTransport._wipe(original)

    def test_cancel_only_signals_and_worker_remains_native_cleanup_owner(self):
        self.new(); reached, release = threading.Event(), threading.Event()
        original = SyntheticPayloadExchange.accept_ready
        errors, close_threads = [], []
        original_close = process._SyntheticPayloadPeer.close
        def ready(codec, frame):
            value = original(codec, frame); reached.set()
            if not release.wait(2): raise AssertionError('test worker release not delivered')
            return value
        def close(child):
            close_threads.append(threading.get_ident()); return original_close(child)
        def run():
            try: self.gate.run()
            except native.SyntheticPayloadTransportError as error: errors.append(error)
        with patch.object(SyntheticPayloadExchange, 'accept_ready', ready), \
                patch.object(process._SyntheticPayloadPeer, 'close', close):
            worker = threading.Thread(target=run); worker.start()
            try:
                self.assertTrue(reached.wait(2))
                caller = threading.get_ident(); started = time.monotonic()
                self.gate.cancel()
                self.assertLess(time.monotonic()-started, .2)
                self.assertEqual(close_threads, [])
            finally:
                release.set(); worker.join(3)
            self.assertFalse(worker.is_alive())
        self.assertEqual(len(errors), 1)
        self.assertTrue(close_threads)
        self.assertNotIn(caller, close_threads)
        self.assertEqual(self.diagnostic()['state'], 'cancelled_before_payload')


